import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { debounce } from './debounce.js';

describe('debounce', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it("calls fn once with the LAST call's arg, waitMs after the last call", () => {
    const fn = vi.fn();
    const debounced = debounce(fn, 100);

    debounced('a');
    vi.advanceTimersByTime(50); // second call arrives mid-window
    debounced('b');
    // Nothing should have fired yet — the timer must have been reset.
    expect(fn).not.toHaveBeenCalled();

    // Fires exactly waitMs after the LAST call (t = 150), not after the first.
    vi.advanceTimersByTime(100);
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveBeenCalledWith('b');
  });

  it('collapses a rapid burst of 10 calls into a single invocation', () => {
    const fn = vi.fn();
    const debounced = debounce(fn, 100);

    for (let i = 0; i < 10; i++) {
      debounced(i);
      vi.advanceTimersByTime(10); // calls at t=0,10,...,90
    }

    vi.advanceTimersByTime(100); // t=190: waitMs past the last call
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveBeenCalledWith(9);
  });

  it('fires again for two bursts separated by more than waitMs', () => {
    const fn = vi.fn();
    const debounced = debounce(fn, 100);

    debounced('burst-1a');
    debounced('burst-1b');
    vi.advanceTimersByTime(500); // well past the wait; burst 1 fires with 'burst-1b'
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveBeenCalledWith('burst-1b');

    debounced('burst-2a');
    debounced('burst-2b');
    vi.advanceTimersByTime(100);
    expect(fn).toHaveBeenCalledTimes(2);
    expect(fn).toHaveBeenLastCalledWith('burst-2b');
  });

  it('cleans up its timer after firing', () => {
    const fn = vi.fn();
    const debounced = debounce(fn, 100);

    debounced('x');
    expect(vi.getTimerCount()).toBe(1);

    vi.advanceTimersByTime(100);
    expect(fn).toHaveBeenCalledTimes(1);
    expect(vi.getTimerCount()).toBe(0);
  });
});

