export function debounce<A>(fn: (arg: A) => void, waitMs: number) {
  let timer: ReturnType<typeof setTimeout> | null = null;
  return (arg: A) => {
    if (timer !== null) {
      clearTimeout(timer);
    }
    timer = setTimeout(() => {
      timer = null;
      fn(arg);
    }, waitMs);
  };
}

